changeSet.sql:
ALTER TABLE settlements ADD COLUMN IF NOT EXISTS trade_date DATE;
UPDATE settlements s
SET trade_date = t.trade_date
FROM trades t
WHERE t.id = s.trade_id AND s.trade_date IS NULL;
ALTER TABLE settlements ALTER COLUMN trade_date SET NOT NULL;
ALTER TABLE settlements DROP CONSTRAINT IF EXISTS fk_settlements_trade;

ALTER INDEX IF EXISTS idx_trades_trade_date RENAME TO idx_trades_legacy_trade_date;
ALTER INDEX IF EXISTS idx_trades_status RENAME TO idx_trades_legacy_status;
ALTER SEQUENCE IF EXISTS trades_id_seq RENAME TO trades_legacy_id_seq;
ALTER TABLE trades RENAME TO trades_legacy;

CREATE TABLE trades (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    trade_ref       VARCHAR(30)   NOT NULL,
    instrument_id   BIGINT        NOT NULL REFERENCES instruments(id),
    counterparty_id BIGINT        NOT NULL REFERENCES counterparties(id),
    asset_class     VARCHAR(20)   NOT NULL,
    side            VARCHAR(4)    NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE          NOT NULL,
    status          VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    modified_at     TIMESTAMP,
    CONSTRAINT pk_trades PRIMARY KEY (id, trade_date),
    CONSTRAINT uk_trades_trade_ref UNIQUE (trade_ref, trade_date)
) PARTITION BY RANGE (trade_date);

CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);
CREATE INDEX idx_trades_instrument ON trades (instrument_id);
CREATE INDEX idx_trades_counterparty ON trades (counterparty_id);

CREATE TABLE trades_2026_04 PARTITION OF trades
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_2026_05 PARTITION OF trades
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_2026_06 PARTITION OF trades
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_2026_07 PARTITION OF trades
    FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE trades_default PARTITION OF trades DEFAULT;

INSERT INTO trades (
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
)
SELECT
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
FROM trades_legacy;

SELECT setval(
    pg_get_serial_sequence('trades', 'id'),
    COALESCE((SELECT MAX(id) FROM trades), 0) + 1,
    false
);

ALTER TABLE settlements
    ADD CONSTRAINT fk_settlements_trade
    FOREIGN KEY (trade_id, trade_date)
    REFERENCES trades (id, trade_date);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM trades) <> (SELECT COUNT(*) FROM trades_legacy) THEN
        RAISE EXCEPTION 'Trade row count changed during partition migration';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM settlements s
        LEFT JOIN trades t
            ON t.id = s.trade_id AND t.trade_date = s.trade_date
        WHERE t.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Settlement lost its trade during partition migration';
    END IF;
END $$;

rollback.sql:
ALTER TABLE settlements DROP CONSTRAINT IF EXISTS fk_settlements_trade;

CREATE TABLE trades_unpartitioned (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trade_ref       VARCHAR(30)   NOT NULL UNIQUE,
    instrument_id   BIGINT        NOT NULL REFERENCES instruments(id),
    counterparty_id BIGINT        NOT NULL REFERENCES counterparties(id),
    asset_class     VARCHAR(20)   NOT NULL,
    side            VARCHAR(4)    NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE          NOT NULL,
    status          VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    modified_at     TIMESTAMP
);

INSERT INTO trades_unpartitioned (
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
)
SELECT
    id, trade_ref, instrument_id, counterparty_id, asset_class, side,
    quantity, price, trade_date, status, deleted_at, created_at, modified_at
FROM trades;

SELECT setval(
    pg_get_serial_sequence('trades_unpartitioned', 'id'),
    COALESCE((SELECT MAX(id) FROM trades_unpartitioned), 0) + 1,
    false
);

DROP TABLE trades;
ALTER TABLE trades_unpartitioned RENAME TO trades;
ALTER SEQUENCE trades_unpartitioned_id_seq RENAME TO trades_id_seq;
CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);

ALTER TABLE settlements DROP COLUMN trade_date;
ALTER TABLE settlements
    ADD CONSTRAINT fk_settlements_trade
    FOREIGN KEY (trade_id) REFERENCES trades (id);
